      this.logger.error("Billing automation worker failed.", error as Error);
      await workerHeartbeat(this.prisma, 'billing', false).catch(() => undefined);
    } finally {
      this.running = false;
    }
  }

parameters.type:
Array<{
      landlordId: string;
      propertyId: string;
      status: string;
      createdCount?: number;
    }>

methods.body:
{
    const dueSoonDays = this.config.get<string>(
      "BILLING_AUTOMATION_REMINDER_DUE_SOON_DAYS",
    ) ?? "60";
    for (const item of results) {
      if (item.status !== "created" || !item.createdCount) continue;
      await this.reminders.enqueue(new Date(), item.landlordId, item.propertyId);
    }
  }

{
    return (
      this.config.get<string>("BILLING_AUTOMATION_SEND_REMINDERS") === "true"
    );
  }

{
    const value = Number.parseInt(raw ?? "", 10);
    return Number.isFinite(value) && value > 0 ? value : fallback;
  }

{
    const landlordId = landlordScopeId(user);
    const requestHash = commandHash({ action, resourceId, input, ...(user.role === AuthRole.STAFF ? { staffId: user.userId, propertyIds: [...(user.propertyIds ?? [])].sort() } : {}) });
    return this.prisma.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${`billing:${landlordId}:${input.requestKey}`}, 0))::text`;
      const previous = await tx.billingCommand.findUnique({ where: { landlordId_requestKey: { landlordId, requestKey: input.requestKey } } });
      if (previous) {
        if (previous.requestHash !== requestHash) billingError('IDEMPOTENCY_KEY_REUSED', 'Request key was already used for a different command.', true);
        return previous.response as Result;
      }
      const result = await perform(tx);
      const response = JSON.parse(JSON.stringify(result)) as Prisma.InputJsonValue;
      await billingAudit(tx, user, action, 'billing', resourceId, JSON.parse(JSON.stringify(input)) as Prisma.InputJsonValue);
      await tx.billingCommand.create({ data: { landlordId, requestKey: input.requestKey, requestHash, response } });
      return result;
    }, { timeout: 20000 });
  }

{
    const landlordId = landlordScopeId(user);
    requiredReason(input.reason);
    if (!input.lines.length) billingError('INVOICE_LINES_REQUIRED', 'Replacement must have invoice lines.');
    const lines = input.lines.map((line, position) => {
      if ((line.kind === 'DISCOUNT') !== (line.unitPrice < 0)) billingError('INVALID_REPLACEMENT_LINE', 'Only discount lines may have a negative unit price.');
      money(Math.abs(line.unitPrice), true);
      money(line.quantity);
      const amount = line.quantity * line.unitPrice;
      money(Math.abs(amount), true);
      return { ...line, position, amount, source: 'REPLACEMENT', sourceId: invoiceId };
    });
    const sumFor = (kinds: string[]) => lines.filter((line) => kinds.includes(line.kind)).reduce((sum, line) => sum + line.amount, 0);
    const totalAmount = money(lines.reduce((sum, line) => sum + line.amount, 0), true);
    return this.commands.execute(user, 'billing.invoice.replace', invoiceId, input, async (tx) => {
      const original = await this.lockInvoice(tx, landlordId, invoiceId);
      this.collectible(original);
      if (original.paidAmount !== 0 || original.payments.length) billingError('INVOICE_HAS_PAYMENTS', 'Use credit/debit notes for an invoice with payment history.', true);
      if (original.replacementInvoice) billingError('INVOICE_ALREADY_REPLACED', 'Invoice already has a replacement.', true);
      const latest = await tx.invoice.aggregate({ where: { leaseId: original.leaseId, billingMonth: original.billingMonth, isDemo: false }, _max: { revision: true } });
      await tx.invoice.update({ where: { id: invoiceId }, data: { status: 'CANCELLED', cancelledAt: new Date(), cancelledNote: input.reason.trim() } });
      await this.cancelLinks(tx, invoiceId);
      const replacement = await tx.invoice.create({ data: {
        leaseId: original.leaseId, tenantId: original.tenantId, roomId: original.roomId,
        billingMonth: original.billingMonth, revision: (latest._max.revision ?? 1) + 1, replacesInvoiceId: original.id,
        rentAmount: sumFor(['RENT']), electricityAmount: sumFor(['ELECTRICITY']), waterAmount: sumFor(['WATER']),
        otherAmount: sumFor(['SERVICE', 'OTHER', 'DISCOUNT', 'SURCHARGE']), totalAmount,
        status: balanceStatus(0, totalAmount), dueDate: input.dueDate ? new Date(input.dueDate) : original.dueDate,
        note: input.reason.trim(), lineItems: { create: lines },
      }, include: invoiceInclude });
      await billingEvent(tx, landlordId, 'invoice.replaced', replacement.id, `invoice.replaced:${replacement.id}`, { originalInvoiceId: invoiceId, replacementInvoiceId: replacement.id, reason: input.reason.trim() });
      return { data: this.billing.serializeInvoice(replacement) };
    });
  }

{
    const landlordId = landlordScopeId(user);
    requiredReason(input.reason);
    if ((input.amount === undefined) === (input.basisPoints === undefined)) billingError('INVALID_ADJUSTMENT', 'Choose a fixed amount or basis points, not both.');
    if (['DISCOUNT', 'TENANT_WAIVER'].includes(input.category) && input.kind !== 'CREDIT') billingError('INVALID_ADJUSTMENT', 'Discounts and waivers require a credit note.');
    if (['LATE_FEE', 'SURCHARGE'].includes(input.category) && input.kind !== 'DEBIT') billingError('INVALID_ADJUSTMENT', 'Surcharges require a debit note.');
    return this.commands.execute(user, 'billing.invoice.adjust', invoiceId, input, async (tx) => {
      const invoice = await this.lockInvoice(tx, landlordId, invoiceId);
      this.collectible(invoice);
      if (input.category === 'LATE_FEE' && (!invoice.dueDate || dueDays(invoice.dueDate) <= 0 || invoice.totalAmount <= invoice.paidAmount)) billingError('INVOICE_NOT_OVERDUE', 'Late fees require an overdue balance.');
      const amount = money(input.amount ?? Math.round(invoice.totalAmount * (input.basisPoints ?? 0) / 10000));
      const signedAmount = input.kind === 'CREDIT' ? -amount : amount;
      const totalAmount = money(invoice.totalAmount + signedAmount, true);
      if (totalAmount < invoice.paidAmount) billingError('CREDIT_EXCEEDS_OPEN_BALANCE', 'Release or reverse the excess allocation before issuing this credit.', true);
      const adjustment = await tx.invoiceAdjustment.create({ data: { invoiceId, kind: input.kind, category: input.category, amount, reason: input.reason.trim(), actorId: user.userId, lineId: randomUUID() } });
      const position = invoice.lineItems.reduce((highest, line) => Math.max(highest, line.position), -1) + 1;
      await tx.invoiceLineItem.create({ data: {
        id: adjustment.lineId, invoiceId, position, kind: input.kind === 'CREDIT' ? 'CREDIT_NOTE' : 'DEBIT_NOTE',
        description: `${input.category}: ${input.reason.trim()}`, quantity: 1, unit: 'lan', unitPrice: signedAmount,
        amount: signedAmount, source: 'ADJUSTMENT_NOTE', sourceId: adjustment.id,
      } });
      const updated = await tx.invoice.update({ where: { id: invoiceId }, data: { totalAmount, otherAmount: invoice.otherAmount + signedAmount, status: balanceStatus(invoice.paidAmount, totalAmount) }, include: invoiceInclude });
      await this.cancelLinks(tx, invoiceId);
      await billingEvent(tx, landlordId, input.kind === 'CREDIT' ? 'invoice.credit_note.created' : 'invoice.debit_note.created', invoiceId, `invoice.adjustment:${adjustment.id}`, { adjustmentId: adjustment.id, amount, reason: input.reason.trim() });
      return { data: this.billing.serializeInvoice(updated) };
    });
  }

{
    const landlordId = landlordScopeId(user);
    money(input.amount);
    return this.commands.execute(user, 'billing.receipt.create', input.tenantId, input, async (tx) => {
      const tenant = await tx.tenant.findFirst({ where: { id: input.tenantId, landlordId, ...tenantScope() }, select: { id: true } });
      if (!tenant) throw new NotFoundException('Tenant not found.');
      const receipt = await tx.billingReceipt.create({ data: { landlordId, tenantId: input.tenantId, amount: input.amount, availableAmount: input.amount, method: input.method, reference: requiredReason(input.reference), paidAt: input.paidAt ? new Date(input.paidAt) : new Date(), actorId: user.userId } });
      await this.allocateLines(tx, receipt, input.allocations);
      await billingEvent(tx, landlordId, 'payment.receipt.created', receipt.id, `receipt.created:${receipt.id}`, { amount: receipt.amount, tenantId: receipt.tenantId });
      return { data: await this.receiptView(tx, receipt.id) };
    });
  }

{
    const landlordId = landlordScopeId(user);
    return this.commands.execute(user, 'billing.receipt.allocate', receiptId, input, async (tx) => {
      const receipt = await this.lockReceipt(tx, landlordId, receiptId);
      await this.allocateLines(tx, receipt, input.allocations);
      await billingEvent(tx, landlordId, 'payment.allocated', receiptId, `receipt.allocated:${landlordId}:${input.requestKey}`, { receiptId, allocations: input.allocations.map((line) => ({ invoiceId: line.invoiceId, amount: line.amount })) });
      return { data: await this.receiptView(tx, receiptId) };
    });
  }

{
    const landlordId = landlordScopeId(user);
    requiredReason(input.reason);
    return this.commands.execute(user, 'billing.receipt.release', allocationId, input, async (tx) => {
      await this.lockReceipt(tx, landlordId, receiptId);
      const allocation = await tx.paymentAllocation.findFirst({ where: { id: allocationId, receiptId }, include: { payment: true } });
      if (!allocation) throw new NotFoundException('Allocation not found.');
      if (allocation.releasedAt) billingError('ALLOCATION_ALREADY_RELEASED', 'Allocation has already been released.', true);
      const invoice = await this.lockInvoice(tx, landlordId, allocation.payment.invoiceId);
      const paidAmount = invoice.paidAmount - allocation.amount;
      if (paidAmount < 0) billingError('PAYMENT_LEDGER_INCONSISTENT', 'Invoice payment ledger requires review.', true);
      await tx.payment.create({ data: { invoiceId: invoice.id, amount: -allocation.amount, method: allocation.payment.method, type: 'REVERSAL', reversalOfPaymentId: allocation.payment.id, note: input.reason.trim() } });
      await tx.paymentAllocation.update({ where: { id: allocationId }, data: { releasedAt: new Date(), releaseReason: input.reason.trim(), releasedBy: user.userId } });
      await tx.invoice.update({ where: { id: invoice.id }, data: { paidAmount, status: balanceStatus(paidAmount, invoice.totalAmount) } });
      await this.cancelLinks(tx, invoice.id);
      await tx.billingReceipt.update({ where: { id: receiptId }, data: { availableAmount: { increment: allocation.amount } } });
      await billingEvent(tx, landlordId, 'payment.allocation.released', receiptId, `allocation.released:${allocationId}`, { allocationId, invoiceId: invoice.id, amount: allocation.amount, reason: input.reason.trim() });
      return { data: await this.receiptView(tx, receiptId) };
    });
  }

{
    const landlordId = landlordScopeId(user);
    money(input.amount); requiredReason(input.reason); requiredReason(input.reference);
    return this.commands.execute(user, 'billing.receipt.refund', receiptId, input, async (tx) => {
      const receipt = await this.lockReceipt(tx, landlordId, receiptId);
      if (input.amount > receipt.availableAmount) billingError('REFUND_EXCEEDS_AVAILABLE', 'Release the allocation first; only unallocated credit can be refunded.', true);
      const refund = await tx.billingRefund.create({ data: { receiptId, amount: input.amount, reason: input.reason.trim(), reference: input.reference.trim(), actorId: user.userId } });
      await tx.billingReceipt.update({ where: { id: receiptId }, data: { availableAmount: { decrement: input.amount }, refundedAmount: { increment: input.amount } } });
      await billingEvent(tx, landlordId, 'payment.refunded', receiptId, `refund.created:${refund.id}`, { refundId: refund.id, amount: input.amount, reference: input.reference.trim() });
      return { data: await this.receiptView(tx, receiptId) };
    });
  }

{
    const rows = await this.prisma.billingReceipt.findMany({ where: { landlordId: landlordScopeId(user), tenant: tenantScope(), ...(tenantId ? { tenantId } : {}) }, include: { allocations: { include: { payment: true }, orderBy: { createdAt: 'asc' } }, refunds: { orderBy: { createdAt: 'asc' } } }, orderBy: { paidAt: 'desc' }, take: 200 });
    return { data: rows };
  }

{
    const landlordId = landlordScopeId(user);
    return this.prisma.$transaction(async (tx) => {
      const invoices = await tx.invoice.findMany({ where: { isDemo: false, status: { not: 'CANCELLED' }, ...(query.tenantId ? { tenantId: query.tenantId } : {}), ...(query.roomId ? { roomId: query.roomId } : {}), room: { ...(query.propertyId ? { propertyId: query.propertyId } : {}), property: propertyWhere(landlordId) } }, include: { room: { include: { property: true } }, tenant: true }, orderBy: [{ dueDate: 'asc' }, { id: 'asc' }] });
      const empty = () => ({ notDue: 0, overdue1To7: 0, overdue8To30: 0, overdueOver30: 0, undated: 0, total: 0, invoiceCount: 0 });
      const summary = empty();
      const groups = new Map<string, ReturnType<typeof empty> & { id: string; name: string }>();
      const items = [];
      for (const invoice of invoices) {
        const remaining = Math.max(invoice.totalAmount - invoice.paidAmount, 0);
        if (!remaining) continue;
        const bucket = agingBucket(invoice.dueDate, now);
        const groupBy = query.groupBy ?? 'tenant';
        const id = groupBy === 'property' ? invoice.room.propertyId : groupBy === 'room' ? invoice.roomId : invoice.tenantId;
        const name = groupBy === 'property' ? invoice.room.property.name : groupBy === 'room' ? invoice.room.name : invoice.tenant.fullName;
        const group = groups.get(id) ?? { id, name, ...empty() };
        summary[bucket] += remaining; summary.total += remaining; summary.invoiceCount++;
        group[bucket] += remaining; group.total += remaining; group.invoiceCount++; groups.set(id, group);
        items.push({ invoiceId: invoice.id, tenantId: invoice.tenantId, tenantName: invoice.tenant.fullName, roomId: invoice.roomId, roomName: invoice.room.name, propertyId: invoice.room.propertyId, propertyName: invoice.room.property.name, dueDate: invoice.dueDate, daysOverdue: invoice.dueDate ? Math.max(dueDays(invoice.dueDate, now), 0) : null, bucket, remainingAmount: remaining });
      }
      const credit = await tx.billingReceipt.aggregate({ where: { landlordId, tenant: tenantScope(), ...(query.tenantId ? { tenantId: query.tenantId } : {}) }, _sum: { availableAmount: true } });
      return { data: { asOf: businessDay(now), timezone: 'Asia/Ho_Chi_Minh', groupBy: query.groupBy ?? 'tenant', summary, groups: [...groups.values()].sort((left, right) => right.total - left.total), invoices: items, tenantUnallocatedCredit: query.propertyId || query.roomId ? null : credit._sum.availableAmount ?? 0 } };
    }, { isolationLevel: Prisma.TransactionIsolationLevel.RepeatableRead });
  }

{
    if (new Set(lines.map((line) => line.invoiceId)).size !== lines.length) billingError('DUPLICATE_ALLOCATION', 'Each invoice may appear only once.');
    const amount = lines.reduce((sum, line) => sum + money(line.amount), 0);
    if (amount > receipt.availableAmount) billingError('ALLOCATIONS_EXCEED_AVAILABLE', 'Allocations exceed unallocated receipt credit.', true);
    for (const line of [...lines].sort((left, right) => left.invoiceId.localeCompare(right.invoiceId))) {
      const invoice = await this.lockInvoice(tx, receipt.landlordId, line.invoiceId);
      this.collectible(invoice);
      if (invoice.tenantId !== receipt.tenantId) billingError('ALLOCATION_TENANT_MISMATCH', 'Payment and invoice must belong to the same tenant.');
      if (line.amount > invoice.totalAmount - invoice.paidAmount) billingError('PAYMENT_EXCEEDS_REMAINING', 'Allocation exceeds invoice balance.', true);
      const payment = await tx.payment.create({ data: { invoiceId: invoice.id, amount: line.amount, method: receipt.method, paidAt: receipt.paidAt, note: receipt.reference } });
      await tx.paymentAllocation.create({ data: { receiptId: receipt.id, paymentId: payment.id, amount: line.amount } });
      const paidAmount = invoice.paidAmount + line.amount;
      await tx.invoice.update({ where: { id: invoice.id }, data: { paidAmount, status: balanceStatus(paidAmount, invoice.totalAmount) } });
      await this.cancelLinks(tx, invoice.id);
    }
    if (amount) await tx.billingReceipt.update({ where: { id: receipt.id }, data: { availableAmount: { decrement: amount } } });
  }

{
    await tx.$queryRaw`SELECT i.id FROM "Invoice" i JOIN "Room" r ON r.id = i."roomId" JOIN "Property" p ON p.id = r."propertyId" WHERE i.id = ${invoiceId} AND p."landlordId" = ${landlordId} FOR UPDATE OF i`;
    const invoice = await tx.invoice.findFirst({ where: { id: invoiceId, room: { property: propertyWhere(landlordId) } }, include: invoiceInclude });
    if (!invoice) throw new NotFoundException('Invoice not found.');
    return invoice;
  }

{
    await tx.$queryRaw`SELECT id FROM "BillingReceipt" WHERE id = ${receiptId} AND "landlordId" = ${landlordId} FOR UPDATE`;
    const receipt = await tx.billingReceipt.findFirst({ where: { id: receiptId, landlordId, tenant: tenantScope() } });
    if (!receipt) throw new NotFoundException('Receipt not found.');
    return receipt;
  }

{
    return tx.billingReceipt.findUniqueOrThrow({ where: { id }, include: { allocations: { include: { payment: true }, orderBy: { createdAt: 'asc' } }, refunds: { orderBy: { createdAt: 'asc' } } } });
  }

{
    if (invoice.isDemo) billingError('DEMO_INVOICE', 'Demo invoices cannot use the production ledger.');
    if (invoice.status === 'CANCELLED') billingError('INVOICE_CANCELLED', 'Cancelled invoices cannot be changed.', true);
  }

{
    await tx.paymentLink.updateMany({ where: { invoiceId, status: 'PENDING' }, data: { status: 'CANCELLED' } });
    await tx.demoCheckoutSession.updateMany({ where: { paymentLink: { invoiceId }, status: 'PENDING' }, data: { status: 'CANCELLED' } });
  }

{
    if (this.config.get('NODE_ENV') === 'test' || this.config.get('BILLING_OUTBOX_WORKER_ENABLED') === 'false') return;
    this.timer = setInterval(() => void this.runOnce(), 30000);
    this.timer.unref();
  }

{
    if (this.running || this.stopping) return;
    this.running = true;
    try {
      await this.reminders.enqueue(now);
      const jobs = await this.prisma.billingOutboxEvent.findMany({ where: { OR: [{ status: 'PENDING', availableAt: { lte: now } }, { status: 'PROCESSING', leaseUntil: { lte: now } }] }, orderBy: { availableAt: 'asc' }, take: 100, select: { id: true } });
      for (const job of jobs) { if (!this.stopping) await this.deliver(job.id); }
      await workerHeartbeat(this.prisma, 'billing-outbox', true);
    } catch {
      this.logger.error('Billing outbox iteration failed. No provider payload logged.');
      await workerHeartbeat(this.prisma, 'billing-outbox', false).catch(() => undefined);
    } finally { this.running = false; }
  }

{
    const owner = randomUUID();
    const claim = await this.prisma.billingOutboxEvent.updateMany({ where: { id, OR: [{ status: 'PENDING', availableAt: { lte: now } }, { status: 'PROCESSING', leaseUntil: { lte: now } }] }, data: { status: 'PROCESSING', leaseOwner: owner, leaseUntil: new Date(now.getTime() + 60000), attempts: { increment: 1 } } });
    if (!claim.count) return;
    const job = await this.prisma.billingOutboxEvent.findUniqueOrThrow({ where: { id } });
    const finish = (data: Prisma.BillingOutboxEventUpdateManyMutationInput) => this.prisma.billingOutboxEvent.updateMany({ where: { id, status: 'PROCESSING', leaseOwner: owner }, data: { ...data, leaseOwner: null, leaseUntil: null } });
    try {
      if (job.type === 'invoice.reminder') {
        const payload = job.payload as { channel: string; policyId: string; policyVersion: number; scheduledDay: string };
        const invoice = await this.reminderInvoice(job.resourceId, job.landlordId);
        const policies = invoice ? await this.prisma.billingReminderPolicy.findMany({ where: { landlordId: job.landlordId, scopeKey: { in: [`property:${invoice.room.propertyId}`, `landlord:${job.landlordId}`] } } }) : [];
        const policy = policies.find((row) => row.propertyId === invoice?.room.propertyId) ?? policies.find((row) => !row.propertyId);
        if (invoice && !tenantAllowsReminder(invoice.tenant.notificationPreference, payload.channel)) {
          await finish({ status: 'SKIPPED', completedAt: now, lastError: 'TENANT_CHANNEL_DISABLED' }); return;
        }
        if (!invoice || !invoice.tenant.isActive || invoice.status === 'CANCELLED' || invoice.paidAmount >= invoice.totalAmount || !invoice.dueDate || !policy || policy.id !== payload.policyId || policy.version !== payload.policyVersion || !policy.channels.includes(payload.channel) || !reminderMatches(policy, invoice.dueDate, now) || payload.scheduledDay !== businessDay(now)) {
          await finish({ status: 'SKIPPED', completedAt: now, lastError: 'NO_LONGER_ELIGIBLE' }); return;
        }
        const remainingAmount = invoice.totalAmount - invoice.paidAmount;
        const title = 'Nhắc thanh toán hóa đơn';
        const body = `Phòng ${invoice.room.name}: còn ${remainingAmount.toLocaleString('vi-VN')} đ, hạn ${invoice.dueDate.toISOString().slice(0, 10)}.`;
        if (payload.channel === 'APP') {
          await this.prisma.billingNotification.upsert({ where: { eventKey: job.eventKey }, create: { tenantId: invoice.tenantId, invoiceId: invoice.id, eventKey: job.eventKey, title, body }, update: {} });
        } else {
          const recipient = payload.channel === 'EMAIL' ? invoice.tenant.user?.email : invoice.tenant.phone;
          if (!recipient) { await finish({ status: 'SKIPPED', completedAt: now, lastError: 'RECIPIENT_MISSING' }); return; }
          await this.post(`BILLING_${payload.channel}`, job.eventKey, { eventId: job.id, type: job.type, channel: payload.channel, recipient, invoiceId: invoice.id, tenantId: invoice.tenantId, remainingAmount, title, body });
        }
      } else {
        const url = this.config.get<string>('BILLING_EVENT_WEBHOOK_URL');
        if (!url) { await finish({ status: 'STORED', completedAt: now }); return; }
        await this.post('BILLING_EVENT', job.eventKey, { eventId: job.id, eventKey: job.eventKey, type: job.type, resourceId: job.resourceId, createdAt: job.createdAt, payload: job.payload });
      }
      await finish({ status: 'COMPLETED', completedAt: now, lastError: null });
    } catch {
      const dead = job.attempts >= 8;
      await finish({ status: dead ? 'DEAD' : 'PENDING', availableAt: new Date(now.getTime() + retryDelay(job.attempts)), lastError: 'DELIVERY_FAILED' });
    }
  }

{
    const rows = await this.prisma.billingOutboxEvent.findMany({ where: { landlordId: landlordScopeId(user) }, orderBy: { createdAt: 'desc' }, take: 200 });
    return { data: rows };
  }

{
    return this.prisma.invoice.findFirst({ where: { id, isDemo: false, room: { property: { landlordId, isArchived: false, landlord: { isActive: true } } } }, include: { room: true, tenant: { include: { user: true, notificationPreference: true } } } });
  }

{
    return this.commands.execute(user, 'billing.outbox.retry', id, input, async (tx) => {
      const result = await tx.billingOutboxEvent.updateMany({ where: { id, landlordId: landlordScopeId(user), status: { in: ['DEAD', 'STORED'] } }, data: { status: 'PENDING', attempts: 0, availableAt: new Date(), lastError: null, completedAt: null } });
      return { data: { retried: result.count === 1 } };
    });
  }

{
    const url = httpsEndpoint(this.config.get<string>(`${prefix}_WEBHOOK_URL`));
    const secret = this.config.get<string>(`${prefix}_WEBHOOK_SECRET`)?.trim();
    if (!url || !secret) throw new Error('PROVIDER_NOT_CONFIGURED');
    const response = await fetch(url, { method: 'POST', redirect: 'error', signal: AbortSignal.timeout(10000), headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${secret}`, 'Idempotency-Key': idempotencyKey }, body: JSON.stringify(body) });
    if (!response.ok) throw new Error('PROVIDER_REJECTED');
  }

{
    const landlordId = landlordScopeId(user);
    if (propertyId) await this.ownedProperty(landlordId, propertyId);
    const scopeKey = propertyId ? `property:${propertyId}` : `landlord:${landlordId}`;
    const [policy, inherited] = await Promise.all([
      this.prisma.billingReminderPolicy.findUnique({ where: { scopeKey } }),
      propertyId ? this.prisma.billingReminderPolicy.findUnique({ where: { scopeKey: `landlord:${landlordId}` } }) : null,
    ]);
    return { data: { policy: policy ?? { scopeKey, landlordId, propertyId: propertyId ?? null, enabled: false, beforeDays: [3, 1], onDueDate: true, overdueDays: [1, 7, 30], channels: ['APP'], version: 0 }, inherited: policy ? null : inherited } };
  }

{
    const landlordId = landlordScopeId(user);
    const scopeKey = input.propertyId ? `property:${input.propertyId}` : `landlord:${landlordId}`;
    if (input.enabled && !input.channels.length) billingError('REMINDER_CHANNEL_REQUIRED', 'An enabled policy must have a delivery channel.');
    return this.commands.execute(user, 'billing.reminder_policy.update', scopeKey, input, async (tx) => {
      if (input.propertyId) {
        const property = await tx.property.findFirst({ where: { id: input.propertyId, landlordId, isArchived: false }, select: { id: true } });
        if (!property) throw new NotFoundException('Property not found.');
      }
      await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${`billing-policy:${scopeKey}`}, 0))::text`;
      const current = await tx.billingReminderPolicy.findUnique({ where: { scopeKey } });
      if ((current?.version ?? 0) !== input.expectedVersion) billingError('REMINDER_POLICY_CONFLICT', 'Policy changed. Reload before saving.', true);
      const values = { enabled: input.enabled, beforeDays: [...input.beforeDays].sort((left, right) => left - right), onDueDate: input.onDueDate, overdueDays: [...input.overdueDays].sort((left, right) => left - right), channels: input.channels };
      const policy = await tx.billingReminderPolicy.upsert({ where: { scopeKey }, create: { landlordId, scopeKey, propertyId: input.propertyId ?? null, ...values }, update: { ...values, version: { increment: 1 } } });
      return { data: policy };
    });
  }

{
    if (propertyId && landlordId) await this.ownedProperty(landlordId, propertyId);
    const policies = await this.prisma.billingReminderPolicy.findMany({ where: landlordId ? { landlordId } : {} });
    const byScope = new Map(policies.map((policy) => [policy.scopeKey, policy]));
    const owners = [...new Set(policies.map((policy) => policy.landlordId))];
    let cursor: string | undefined;
    let queued = 0;
    while (owners.length) {
      const invoices = await this.prisma.invoice.findMany({ where: { isDemo: false, status: { in: ['UNPAID', 'PARTIAL'] }, dueDate: { not: null }, room: { ...(propertyId ? { propertyId } : {}), property: { landlordId: { in: owners }, isArchived: false, landlord: { isActive: true } } } }, include: { room: { include: { property: true } }, tenant: { include: { notificationPreference: true } } }, orderBy: { id: 'asc' }, take: 250, ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}) });
      for (const invoice of invoices) {
        const policy = byScope.get(`property:${invoice.room.propertyId}`) ?? byScope.get(`landlord:${invoice.room.property.landlordId}`);
        if (!policy || !invoice.dueDate || invoice.totalAmount <= invoice.paidAmount || !reminderMatches(policy, invoice.dueDate, now)) continue;
        for (const channel of policy.channels) {
          if (!invoice.tenant.isActive || !tenantAllowsReminder(invoice.tenant.notificationPreference, channel)) continue;
          const eventKey = `reminder:${invoice.id}:${invoice.dueDate.toISOString().slice(0, 10)}:${businessDay(now)}:${channel}`;
          const inserted = await this.prisma.billingOutboxEvent.createMany({ data: [{ landlordId: policy.landlordId, eventKey, type: 'invoice.reminder', resourceId: invoice.id, availableAt: now, payload: { invoiceId: invoice.id, channel, policyId: policy.id, policyVersion: policy.version, scheduledDay: businessDay(now) } }], skipDuplicates: true });
          queued += inserted.count;
        }
      }
      if (invoices.length < 250) break;
      cursor = invoices[invoices.length - 1].id;
    }
    return { data: { queued, businessDay: businessDay(now) } };
  }

{
    const property = await this.prisma.property.findFirst({ where: { id, landlordId }, select: { id: true } });
    if (!property) throw new NotFoundException('Property not found.');
  }

{
    if (typeof propertyId !== 'string' || !propertyId.trim()) billingError('TARIFF_PROPERTY_REQUIRED', 'Choose a property before listing tariffs.');
    await this.property(this.prisma, landlordScopeId(user), propertyId);
    return { data: await this.prisma.billingTariffVersion.findMany({ where: { propertyId, landlordId: landlordScopeId(user) }, orderBy: [{ effectiveFrom: 'desc' }, { version: 'desc' }] }) };
  }

{
    const landlordId = landlordScopeId(user);
    const effectiveFrom = tariffMonth(input.effectiveFrom, businessMonth());
    if (effectiveFrom < businessMonth()) billingError('TARIFF_BACKDATED', 'Tariffs cannot be backdated.');
    validateTiers(input.tiers);
    if (input.kind === 'SERVICE' && input.tiers.length) billingError('SERVICE_TIERS_UNSUPPORTED', 'Fixed service charges cannot have usage tiers.');
    const key = input.kind === 'SERVICE' ? serviceKey(input.serviceKey) : input.kind.toLowerCase();
    if (!key || !input.name.trim() || !input.unit.trim()) billingError('INVALID_TARIFF', 'Tariff key, name and unit are required.');
    const scopeKey = input.roomId ? `room:${input.roomId}` : `property:${input.propertyId}`;
    return this.commands.execute(user, 'billing.tariff.propose', scopeKey, input, async (tx) => {
      await this.lockProperty(tx, landlordId, input.propertyId);
      if (input.roomId && !(await tx.room.findFirst({ where: { id: input.roomId, propertyId: input.propertyId, isActive: true }, select: { id: true } }))) throw new NotFoundException('Room not found.');
      const previous = await tx.billingTariffVersion.aggregate({ where: { scopeKey, serviceKey: key }, _max: { version: true } });
      const tariff = await tx.billingTariffVersion.create({ data: { landlordId, propertyId: input.propertyId, roomId: input.roomId ?? null, scopeKey, serviceKey: key, name: input.name.trim(), kind: input.kind, unit: input.unit.trim(), amount: input.amount, tiers: input.tiers.map((tier) => ({ upTo: tier.upTo ?? null, unitPrice: tier.unitPrice })), effectiveFrom, version: (previous._max.version ?? 0) + 1, makerId: user.userId, isActive: input.isActive, reason: requiredReason(input.reason) } });
      await billingEvent(tx, landlordId, 'tariff.proposed', tariff.id, `tariff.proposed:${tariff.id}`, { propertyId: tariff.propertyId, version: tariff.version });
      return { data: tariff };
    });
  }

{
    const ids = scopedPropertyIds();
    const tariff = await this.prisma.billingTariffVersion.findFirst({ where: { id, landlordId: landlordScopeId(user), ...(ids ? { propertyId: { in: ids } } : {}) } });
    if (!tariff) throw new NotFoundException('Tariff not found.');
    const [rooms, previous, issuedInvoices, lockedPeriods, latest, overrides] = await Promise.all([
      this.prisma.room.findMany({ where: { propertyId: tariff.propertyId, ...(tariff.roomId ? { id: tariff.roomId } : {}), isActive: true }, select: { id: true, name: true } }),
      this.prisma.billingTariffVersion.findFirst({ where: { id: { not: tariff.id }, scopeKey: tariff.scopeKey, serviceKey: tariff.serviceKey, state: 'APPROVED', effectiveFrom: { lte: tariff.effectiveFrom } }, orderBy: [{ effectiveFrom: 'desc' }, { version: 'desc' }] }),
      this.prisma.invoice.count({ where: { isDemo: false, billingMonth: { gte: tariff.effectiveFrom }, room: { propertyId: tariff.propertyId, ...(tariff.roomId ? { id: tariff.roomId } : {}) } } }),
      this.prisma.billingPeriodLock.count({ where: { propertyId: tariff.propertyId, month: { gte: tariff.effectiveFrom } } }),
      this.prisma.billingTariffVersion.findFirst({ where: { scopeKey: tariff.scopeKey, serviceKey: tariff.serviceKey, state: 'APPROVED' }, orderBy: [{ effectiveFrom: 'desc' }, { version: 'desc' }] }),
      tariff.roomId ? Promise.resolve([]) : this.prisma.billingTariffVersion.findMany({ where: { propertyId: tariff.propertyId, roomId: { not: null }, serviceKey: tariff.serviceKey, state: 'APPROVED', effectiveFrom: { lte: tariff.effectiveFrom } }, select: { roomId: true } }),
    ]);
    const overrideIds = new Set(overrides.map((row) => row.roomId));
    const blockingReasons = [
      ...(issuedInvoices ? ['ISSUED_INVOICES'] : []),
      ...(lockedPeriods ? ['LOCKED_PERIODS'] : []),
      ...(tariff.state !== 'PROPOSED' ? ['ALREADY_REVIEWED'] : []),
      ...(tariff.effectiveFrom < businessMonth() ? ['BACKDATED'] : []),
      ...(latest && latest.effectiveFrom >= tariff.effectiveFrom ? ['EFFECTIVE_ORDER'] : []),
    ];
    return { data: { proposed: tariff, previous, rooms: rooms.filter((room) => !overrideIds.has(room.id)), overriddenRooms: rooms.filter((room) => overrideIds.has(room.id)), issuedInvoices, lockedPeriods, blockingReasons, canApprove: !blockingReasons.length } };
  }

{
    return this.commands.execute(user, 'billing.tariff.review', id, input, async (tx) => {
      const ids = scopedPropertyIds();
      const tariff = await tx.billingTariffVersion.findFirst({ where: { id, landlordId: landlordScopeId(user), ...(ids ? { propertyId: { in: ids } } : {}) } });
      if (!tariff) throw new NotFoundException('Tariff not found.');
      await this.lockProperty(tx, landlordScopeId(user), tariff.propertyId);
      const current = await tx.billingTariffVersion.findUniqueOrThrow({ where: { id } });
      if (current.state !== 'PROPOSED') billingError('TARIFF_ALREADY_REVIEWED', 'Tariff proposal has already been reviewed.', true);
      if (input.decision === 'APPROVED') {
        if (current.effectiveFrom < businessMonth()) billingError('TARIFF_BACKDATED', 'Tariff effective month is in the past.');
        const [issued, locked, latest] = await Promise.all([
          tx.invoice.count({ where: { isDemo: false, billingMonth: { gte: current.effectiveFrom }, room: { propertyId: current.propertyId, ...(current.roomId ? { id: current.roomId } : {}) } } }),
          tx.billingPeriodLock.count({ where: { propertyId: current.propertyId, month: { gte: current.effectiveFrom } } }),
          tx.billingTariffVersion.findFirst({ where: { scopeKey: current.scopeKey, serviceKey: current.serviceKey, state: 'APPROVED' }, orderBy: { effectiveFrom: 'desc' } }),
        ]);
        if (issued || locked) billingError('TARIFF_PERIOD_CLOSED', 'Tariff affects an invoiced or locked billing period.', true);
        if (latest && latest.effectiveFrom >= current.effectiveFrom) billingError('TARIFF_EFFECTIVE_ORDER', 'Approved versions require a later effective month.', true);
      }
      const reviewed = await tx.billingTariffVersion.update({ where: { id }, data: { state: input.decision, checkerId: user.userId, reviewReason: requiredReason(input.reason), reviewedAt: new Date() } });
      await billingEvent(tx, landlordScopeId(user), 'tariff.reviewed', id, `tariff.reviewed:${id}`, { state: input.decision, propertyId: tariff.propertyId });
      return { data: reviewed };
    });
  }

{
    const month = tariffMonth(input.month, businessMonth());
    return this.commands.execute(user, 'billing.period.lock', input.propertyId, input, async (tx) => {
      await this.lockProperty(tx, landlordScopeId(user), input.propertyId);
      const lock = await tx.billingPeriodLock.upsert({ where: { propertyId_month: { propertyId: input.propertyId, month } }, create: { propertyId: input.propertyId, month, reason: requiredReason(input.reason), actorId: user.userId }, update: {} });
      return { data: lock };
    });
  }

{
    const billingMonth = tariffMonth(input.billingMonth, businessMonth());
    return this.prisma.$transaction(async (tx) => {
      const lease = await tx.lease.findFirst({ where: { id: input.leaseId, room: { property: propertyWhere(landlordScopeId(user)) } } });
      if (!lease) throw new NotFoundException('Lease not found.');
      const readings = await tx.meterReading.findMany({ where: { roomId: lease.roomId, billingMonth } });
      const result = await pricedInvoiceLines(tx, lease, readings, billingMonth, input.otherAmount ?? 0);
      return { data: { ...result, leaseId: lease.id, billingMonth, preview: true, missingUtilities: ['ELECTRICITY', 'WATER'].filter((kind) => !readings.some((reading) => reading.utilityType === kind)) } };
    }, { isolationLevel: Prisma.TransactionIsolationLevel.RepeatableRead });
  }

{
    const property = await client.property.findFirst({ where: { id, ...propertyWhere(landlordId), isArchived: false }, select: { id: true } });
    if (!property) throw new NotFoundException('Property not found.');
    return property;
  }

{
    await tx.$queryRaw`SELECT id FROM "Property" WHERE id = ${id} AND "landlordId" = ${landlordId} FOR UPDATE`;
    return this.property(tx, landlordId, id);
  }

{
    return this.billing.activeLeases(landlordScopeId(user), month);
  }

{
    return this.billing.listMeterReadings(landlordScopeId(user), roomId, month);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.createMeterReading(landlordId, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.meter_reading_create",
      resourceType: "meter_reading",
      resourceId: result.data.id,
      summary: "Tạo chỉ số điện/nước",
      metadata: {
        roomId: result.data.roomId,
        utilityType: result.data.utilityType,
        amount: result.data.amount,
      },
    });
    return result;
  }

{
    return this.billing.listInvoices(
      landlordScopeId(user),
      status,
      month,
      propertyId,
      aging,
      dueSoonDays,
    );
  }

{
    return this.billing.reminders(
      landlordScopeId(user),
      propertyId,
      dueSoonDays,
    );
  }

{
    const result = await this.reminderPolicies.enqueue(new Date(), landlordScopeId(user), propertyId);
    return { data: { total: result.data.queued, sent: 0, failed: 0, skipped: 0, queued: result.data.queued, results: [] } };
  }

{
    return this.billing.bulkInvoicePreflight(landlordScopeId(user), input);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.createBulkInvoices(landlordId, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.invoice_bulk_create",
      resourceType: "invoice",
      summary: `Tạo hàng loạt ${result.data.createdCount} hóa đơn`,
      metadata: {
        propertyId: result.data.propertyId,
        billingMonth: result.data.billingMonth,
        createdCount: result.data.createdCount,
        existingCount: result.data.existingCount,
      },
    });
    return result;
  }

{
    return this.billing.billingAutomation(
      landlordScopeId(user),
      query.propertyId,
    );
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.updateBillingAutomation(
      landlordId,
      input,
    );
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.automation_update",
      resourceType: "billing_automation",
      resourceId: result.data.id || input.propertyId,
      summary: `${input.isEnabled ? "Bật" : "Tắt"} tự động lập hóa đơn`,
      metadata: {
        propertyId: input.propertyId,
        isEnabled: input.isEnabled,
        invoiceDay: input.invoiceDay,
        dueDay: input.dueDay,
      },
    });
    return result;
  }

{
    return this.billing.billingAutomationPreview(landlordScopeId(user), input);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.runBillingAutomation(landlordId, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.automation_run",
      resourceType: "invoice",
      summary: `Chạy tự động lập ${result.data.result.createdCount} hóa đơn`,
      metadata: {
        propertyId: input.propertyId,
        billingMonth: result.data.result.billingMonth,
        createdCount: result.data.result.createdCount,
        existingCount: result.data.result.existingCount,
      },
    });
    return result;
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.createInvoice(landlordId, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.invoice_create",
      resourceType: "invoice",
      resourceId: result.data.id,
      summary: `Tạo hóa đơn ${result.data.tenantName ?? ""}`.trim(),
      metadata: {
        leaseId: result.data.leaseId,
        totalAmount: result.data.totalAmount,
      },
    });
    return result;
  }

{
    return this.billing.getInvoice(landlordScopeId(user), id);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.updateInvoice(landlordId, id, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.invoice_update",
      resourceType: "invoice",
      resourceId: id,
      summary: "Cập nhật hóa đơn",
      metadata: { dueDate: input.dueDate ?? null },
    });
    return result;
  }

{
    const landlordId = landlordScopeId(user);
    return this.billing.cancelInvoice(landlordId, id, input, user);
  }

{
    return this.ledger.replace(user, id, input);
  }

{
    return this.ledger.adjust(user, id, input);
  }

{
    return this.ledger.aging(user, query);
  }

{
    return this.ledger.receipts(user, tenantId);
  }

{
    return this.ledger.createReceipt(user, input);
  }

{
    return this.ledger.allocate(user, id, input);
  }

{
    return this.ledger.release(user, id, allocationId, input);
  }

{
    return this.ledger.refund(user, id, input);
  }

{
    return this.reminderPolicies.policy(user, propertyId);
  }

{
    return this.reminderPolicies.save(user, input);
  }

{
    return this.reminderPolicies.enqueue(new Date(), landlordScopeId(user), propertyId);
  }

{
    return this.outbox.list(user);
  }

{
    return this.outbox.retry(user, id, input);
  }

{
    return this.tariffs.list(user, propertyId);
  }

{
    return this.tariffs.propose(user, input);
  }

{
    return this.tariffs.impact(user, id);
  }

{
    return this.tariffs.review(user, id, input);
  }

{
    return this.tariffs.lockPeriod(user, input);
  }

{
    return this.tariffs.preview(user, input);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.recordPayment(landlordId, id, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.payment_record",
      resourceType: "invoice",
      resourceId: id,
      summary: `Ghi nhận thanh toán ${input.amount}`,
      metadata: { amount: input.amount, method: input.method },
    });
    return result;
  }

{
    return this.billing.listPaymentProofs(landlordScopeId(user), status);
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.reviewPaymentProof(
      landlordId,
      id,
      user.userId,
      input,
    );
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.payment_proof_review",
      resourceType: "payment_proof",
      resourceId: id,
      summary: `${input.status === "approved" ? "Duyệt" : "Từ chối"} bằng chứng thanh toán`,
      metadata: { status: input.status },
    });
    return result;
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.billing.reversePayment(
      landlordId,
      invoiceId,
      paymentId,
      input,
    );
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: "billing.payment_reverse",
      resourceType: "invoice",
      resourceId: invoiceId,
      summary: "Đảo thanh toán",
      metadata: { paymentId, note: input.note ?? null },
    });
    return result;
  }

decorators:
@Module({
