    const ids = input.tenantIds ?? [];
    if (await this.prisma.tenant.count({ where: { id: { in: ids }, landlordId, isActive: true } }) !== ids.length) throw new BadRequestException('Danh sách người nhận không hợp lệ.');
    return ids;
  }

{
