parameters.type:
{
      id: string;
      purpose: string;
      sentAt: Date | null;
      createdAt: Date;
      updatedAt: Date;
      payload: unknown;
    }

methods.body:
{
    return {
      ...delivery,
      read: this.isTenantZaloMessage(delivery) || readIds.has(delivery.id),
      contact: {
        landlordName: tenant.landlord.fullName,
        tenantZaloPhone: tenant.phone,
      },
      sentAt: delivery.sentAt?.toISOString() ?? null,
      createdAt: delivery.createdAt.toISOString(),
      updatedAt: delivery.updatedAt.toISOString(),
    };
  }

{
    const payload =
      delivery.payload && typeof delivery.payload === "object"
        ? (delivery.payload as Record<string, unknown>)
        : {};
    return (
      delivery.purpose === "tenant_manual_message" ||
      payload.sender_role === "tenant" ||
      payload.direction === "tenant_to_landlord"
    );
  }

{
    const normalized = (value ?? "bank_transfer").toUpperCase();
    if (normalized === "CASH") return PaymentMethod.CASH;
    if (normalized === "OTHER") return PaymentMethod.OTHER;
    return PaymentMethod.BANK_TRANSFER;
  }

{
    const normalized = value.toUpperCase();
    return normalized in MaintenancePriority
      ? MaintenancePriority[normalized as keyof typeof MaintenancePriority]
      : MaintenancePriority.MEDIUM;
  }

{
    return (
      values
        ?.map((value) => value.trim())
        .filter((value) => value.length > 0) ?? []
    );
  }

{
    return (
      !invoice.isDemo &&
      invoice.status !== InvoiceStatus.PAID &&
      invoice.status !== InvoiceStatus.CANCELLED &&
      invoice.totalAmount - invoice.paidAmount > 0
    );
  }

{
    if (!invoice.dueDate || !this.isCollectible(invoice)) return 0;
    return Math.max(
      0,
      Math.floor(
        (this.utcDateOnly(new Date()).getTime() -
          this.utcDateOnly(invoice.dueDate).getTime()) /
          86_400_000,
      ),
    );
  }

{
    if (!invoice.dueDate || !this.isCollectible(invoice)) return null;
    return Math.floor(
      (this.utcDateOnly(invoice.dueDate).getTime() -
        this.utcDateOnly(new Date()).getTime()) /
        86_400_000,
    );
  }

{
    return new Date(
      Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()),
    );
  }

{
    const landlordId = landlordScopeId(user);
    const result = await this.invites.create(landlordId, tenantId, input);
    await this.audit.recordSafe({
      landlordId,
      actor: user,
      action: 'tenant.invite_create',
      resourceType: 'tenant',
      resourceId: tenantId,
      summary: 'Tạo lời mời tenant',
      metadata: { email: input.email.trim().toLowerCase() },
    });
    return result;
  }

{
    return this.invites.accept(input);
  }

{
    return this.prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT "id" FROM "Tenant" WHERE "id" = ${tenantId} FOR UPDATE`;
    const tenant = await tx.tenant.findFirst({
      where: { id: tenantId, landlordId, isActive: true, ...tenantScope() },
      select: { id: true, userId: true },
    });
    if (!tenant) throw tenantNotFound();
    if (tenant.userId) throw tenantAccountExists();

    const email = input.email.trim().toLowerCase();
    const existingUser = await tx.user.findUnique({ where: { email } });
    if (existingUser) throw emailAlreadyRegistered();
    const now = new Date();
    const latest = await tx.tenantInvite.findFirst({ where: { tenantId }, orderBy: { createdAt: 'desc' } });
