    const endpoint = httpsEndpoint(this.config.get<string>('SUPPORT_SCAN_WEBHOOK_URL'));
    const secret = this.config.get<string>('SUPPORT_SCAN_WEBHOOK_SECRET')?.trim();
    if (!endpoint || !secret) throw new ServiceUnavailableException('Attachment scanner is not configured.');
    const sha256 = createHash('sha256').update(bytes).digest('hex');
    try {
      const response = await fetch(endpoint, { method: 'POST', redirect: 'error', signal: AbortSignal.timeout(15000),
        headers: { 'content-type': mime, 'x-content-sha256': sha256, authorization: `Bearer ${secret}` }, body: new Uint8Array(bytes) });
      if (!response.ok) { await response.body?.cancel(); throw new Error(); }
      const text = await response.text();
      if (text.length > 4096) throw new Error();
      const result = JSON.parse(text) as { sha256?: string; verdict?: string };
      if (result.sha256 !== sha256) throw new Error();
      if (result.verdict === 'INFECTED') throw new BadRequestException('Attachment rejected by malware scanner.');
      if (result.verdict !== 'CLEAN') throw new Error();
      return sha256;
    } catch (error) {
